//! 🌱️ The intrinsic wire bridge borrows the original value and orders only its actual object headers under bounded grants.
use semio_framework_value::{DslValue,ValueError,ValueRefusalKind,RetirementDemand,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,retained_clone::retained_clone_grant_admits};
use semio_framework_dsl_record::{BorrowedFieldSpec,BorrowedRecordSpec,BorrowedShape,DslField,RecordLayout,native_encoding::{FieldProjectionSource,FieldProjectionView}};
use std::{cmp::Ordering,mem::size_of};
static FIELDS:[BorrowedFieldSpec;1]=[BorrowedFieldSpec::new(1,"value",BorrowedShape::Value)];
/// 🔎️ This exact field-one view is the canonical container-less wire value schema, without an owned RecordValue mirror.
pub struct BorrowedWireValue<'a>{value:&'a DslValue}
impl<'a> BorrowedWireValue<'a>{pub const RECORD:BorrowedRecordSpec=BorrowedRecordSpec{keyword:None,layout:RecordLayout::Lines,fields:&FIELDS};pub fn new(value:&'a DslValue)->Self{Self{value}}}
impl FieldProjectionSource for BorrowedWireValue<'_>{fn projection_identity(&self)->usize{self.value as*const _ as usize}fn projection_view(&self,path:&[usize])->Result<FieldProjectionView<'_>,ValueError>{if path.is_empty(){return Ok(FieldProjectionView::Record(&[1]))}if path[0]!=0{return Err(invalid())}DslField::projection_view(self.value,&path[1..])}fn projection_key(&self,path:&[usize],index:usize)->Result<&str,ValueError>{if path.first()!=Some(&0){return Err(invalid())}DslField::projection_key(self.value,&path[1..],index)}}
#[derive(Clone,Copy,Default)]
struct Frame{phase:u8,index:usize,left:usize,right:usize,offset:usize}
/// 🧵️ The same sixty-four source path bound as the retained Pack cursor limits fixed traversal metadata; no payload or key is copied.
pub struct WireValueKeyOrderCursor{source:Option<(usize,u64)>,path:[usize;64],frames:[Frame;64],depth:usize,started:bool,complete:bool,closed:bool}
impl Default for WireValueKeyOrderCursor{fn default()->Self{Self{source:None,path:[0;64],frames:[Frame::default();64],depth:0,started:false,complete:false,closed:false}}}
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"original wire value changed its source, epoch, object path or key order cursor")}
fn node<'a>(mut value:&'a DslValue,path:&[usize])->Result<&'a DslValue,ValueError>{for index in path{value=match value{DslValue::Array(rows)=>rows.get(*index),DslValue::Object(rows)=>rows.get(*index).map(|(_,value)|value),_=>None}.ok_or_else(invalid)?;}Ok(value)}
fn node_mut<'a>(mut value:&'a mut DslValue,path:&[usize])->Result<&'a mut DslValue,ValueError>{for index in path{value=match value{DslValue::Array(rows)=>rows.get_mut(*index),DslValue::Object(rows)=>rows.get_mut(*index).map(|(_,value)|value),_=>None}.ok_or_else(invalid)?;}Ok(value)}
impl WireValueKeyOrderCursor{
 fn validate(&self,value:&DslValue,epoch:u64)->Result<(),ValueError>{if self.closed||self.source.is_some_and(|source|source!=(value as*const _ as usize,epoch)){return Err(invalid())}Ok(())}
 fn comparison(&self,value:&DslValue)->Result<(usize,Option<Ordering>),ValueError>{let frame=self.frames[self.depth];let DslValue::Object(rows)=node(value,&self.path[..self.depth])?else{return Err(invalid())};let(left,right)=(&rows[frame.right-1].0,&rows[frame.right].0);let count=(left.len().min(right.len())-frame.offset).min(64);let order=left.as_bytes()[frame.offset..frame.offset+count].cmp(&right.as_bytes()[frame.offset..frame.offset+count]);let order=if order!=Ordering::Equal{Some(order)}else if frame.offset+count==left.len().min(right.len()){Some(left.len().cmp(&right.len()))}else{None};Ok((count,order))}
 pub fn demands(&self,value:&DslValue,epoch:u64)->Result<RetirementDemand,ValueError>{self.validate(value,epoch)?;if self.complete{return Ok(Default::default())}let mut copy=2*size_of::<Frame>()+size_of::<(usize,bool)>();if self.started&&self.frames[self.depth].phase==1{let frame=self.frames[self.depth];let DslValue::Object(rows)=node(value,&self.path[..self.depth])?else{return Err(invalid())};if frame.left<rows.len()&&frame.right>0{let(count,order)=self.comparison(value)?;copy=copy.checked_add(2*count).and_then(|copy|copy.checked_add(usize::from(order==Some(Ordering::Greater))*3*size_of::<(String,DslValue)>())).ok_or_else(invalid)?;}}Ok(RetirementDemand{copy_bytes:copy,depth:self.depth+1,..Default::default()})}
 pub fn advance(&mut self,value:&mut DslValue,epoch:u64,grant:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.demands(value,epoch)?;if self.complete{return Ok(RetainedCloneStep::Complete(Default::default()))}if !retained_clone_grant_admits(grant,d){return Ok(RetainedCloneStep::Progress(Default::default()))}self.source=Some((value as*const _ as usize,epoch));if !self.started{self.started=true;}else{let frame=self.frames[self.depth];match frame.phase{0=>match node(value,&self.path[..self.depth])?{DslValue::Object(_)=>{self.frames[self.depth].phase=1;self.frames[self.depth].left=1;self.frames[self.depth].right=1;},DslValue::Array(_)=>self.frames[self.depth].phase=2,_=>self.pop()},1=>{let DslValue::Object(rows)=node(value,&self.path[..self.depth])?else{return Err(invalid())};if frame.left==rows.len()||rows.is_empty(){self.frames[self.depth].phase=2;}else if frame.right==0{self.frames[self.depth].left+=1;self.frames[self.depth].right=self.frames[self.depth].left;self.frames[self.depth].offset=0;}else{let(count,order)=self.comparison(value)?;match order{None=>self.frames[self.depth].offset+=count,Some(Ordering::Greater)=>{let DslValue::Object(rows)=node_mut(value,&self.path[..self.depth])?else{return Err(invalid())};rows.swap(frame.right-1,frame.right);self.frames[self.depth].right-=1;self.frames[self.depth].offset=0;},Some(_)=>{self.frames[self.depth].left+=1;self.frames[self.depth].right=self.frames[self.depth].left;self.frames[self.depth].offset=0;}}}},2=>{let length=match node(value,&self.path[..self.depth])?{DslValue::Array(rows)=>rows.len(),DslValue::Object(rows)=>rows.len(),_=>return Err(invalid())};if frame.index==length{self.pop();}else{if self.depth+1==self.frames.len(){return Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,"original wire value exceeds the retained Pack source path bound"))}self.path[self.depth]=frame.index;self.frames[self.depth].index+=1;self.depth+=1;self.frames[self.depth]=Frame::default();}},_=>return Err(invalid())}}let p=RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()};Ok(if self.complete{RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})}
 fn pop(&mut self){if self.depth==0{self.complete=true;}else{self.depth-=1;}}
 pub fn is_complete(&self)->bool{self.complete}
 pub fn close(&mut self){self.closed=true;self.source=None;}
 pub fn terminal_is_empty(&self)->bool{self.closed&&self.source.is_none()}
}

